#include <stdio.h>
#include <stdbool.h>

#define MAXN 10

int n, perm[MAXN];
bool used[MAXN];
int count = 0;

/* 回溯: 确定第 k 个位置的元素(排列树) */
void backtrack(int k) {
    if (k == n) {                        /* 得到一个完整排列(叶子) */
        for (int i = 0; i < n; i++) printf("%d ", perm[i]);
        printf("\n");
        count++;
        return;
    }
    for (int x = 1; x <= n; x++) {       /* 候选集合 1..n */
        if (used[x]) continue;           /* 约束函数: x 已被使用 */
        used[x] = true;                  /* 选择 */
        perm[k] = x;
        backtrack(k + 1);                /* 递归进入下一层 */
        used[x] = false;                 /* 撤销选择(回溯) */
    }
}

int main(void) {
    printf("请输入 n (1~8, 排列数为 n!): ");
    if (scanf("%d", &n) != 1 || n < 1 || n > 8) { printf("输入无效!\n"); return 1; }
    backtrack(0);
    printf("共 %d 个排列\n", count);
    return 0;
}

#include <stdio.h>
#include <stdbool.h>

#define MAXN 12

int n, sol = 0;
int col[MAXN];                 /* col[r]: 第 r 行皇后所在列(仅记录) */
bool used_col[MAXN];           /* 列占用 */
bool diag1[2 * MAXN];          /* 主对角线 r-c+n-1 占用 */
bool diag2[2 * MAXN];          /* 副对角线 r+c 占用 */

void dfs(int r) {
    if (r == n) { sol++; return; }              /* 全部放置完毕 */
    for (int c = 0; c < n; c++) {
        if (used_col[c] || diag1[r - c + n - 1] || diag2[r + c])
            continue;                          /* 约束函数: 三类冲突 */
        col[r] = c;
        used_col[c] = diag1[r - c + n - 1] = diag2[r + c] = true;
        dfs(r + 1);                            /* 递归 */
        used_col[c] = diag1[r - c + n - 1] = diag2[r + c] = false;  /* 撤销 */
    }
}

int main(void) {
    printf("请输入 n (1~12, 建议 n<=10 快速出结果): ");
    if (scanf("%d", &n) != 1 || n < 1 || n > 12) { printf("输入无效!\n"); return 1; }
    dfs(0);
    printf("N=%d 的皇后放置方案数: %d\n", n, sol);
    return 0;
}

