#include <stdio.h>

int n, target, a[30], path[30], ans = 0;

/* 回溯: 已决策前 i 个元素, 当前和 sum, 剩余元素总和 rest, 已选 len 个 */
void dfs(int i, int sum, int rest, int len) {
    if (sum == target) {                       /* 找到一个方案 */
        printf("方案: ");
        for (int k = 0; k < len; k++) printf("%d ", path[k]);
        printf("\n");
        ans++;
        return;                                /* 元素为正, 继续加只会超界 */
    }
    if (i == n || sum > target) return;        /* 越界/超界剪枝 */
    if (sum + rest < target) return;           /* 剩余和剪枝: 全选也不够 */
    path[len] = a[i];                          /* 选 a[i] */
    dfs(i + 1, sum + a[i], rest - a[i], len + 1);
    dfs(i + 1, sum, rest - a[i], len);         /* 不选 a[i] */
}

int main(void) {
    printf("请输入 n 与目标和 target: ");
    if (scanf("%d %d", &n, &target) != 2 || n < 1 || n > 25 || target < 0) {
        printf("输入无效!\n"); return 1;
    }
    printf("请输入 %d 个正整数: ", n);
    int rest = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
        if (a[i] <= 0) { printf("输入无效!\n"); return 1; }
        rest += a[i];
    }
    dfs(0, 0, rest, 0);
    printf("共 %d 个方案\n", ans);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

/* 0-1 背包: 优先队列式分支限界(LC 搜索), 上界 = 分数背包贪心 */
typedef struct { int w, v; double r; } Item;

typedef struct { int i, w, v; double bound; } Node;

int cmp_item(const void *x, const void *y) {
    Item *a = (Item *)x, *b = (Item *)y;
    if (a->r > b->r) return -1;
    if (a->r < b->r) return 1;
    return 0;
}

/* 上界函数: 从物品 i 起按单位价值降序贪心(允许部分装入) */
double ub(int i, int w, int v, Item it[], int n, int W) {
    double b = v;
    for (int j = i; j < n && w < W; j++) {
        if (w + it[j].w <= W) { w += it[j].w; b += it[j].v; }
        else { b += (double)(W - w) * it[j].r; w = W; }
    }
    return b;
}

#define MAXH (1 << 20)
Node heap[MAXH];
int hsz = 0;

void push(Node x) {                        /* 按 bound 降序的最大堆 */
    int p = hsz++;
    heap[p] = x;
    while (p > 0) {
        int q = (p - 1) / 2;
        if (heap[q].bound >= heap[p].bound) break;
        Node t = heap[p]; heap[p] = heap[q]; heap[q] = t;
        p = q;
    }
}

Node pop(void) {
    Node top = heap[0];
    heap[0] = heap[--hsz];
    int p = 0;
    for (;;) {
        int l = 2 * p + 1, r = 2 * p + 2, m = p;
        if (l < hsz && heap[l].bound > heap[m].bound) m = l;
        if (r < hsz && heap[r].bound > heap[m].bound) m = r;
        if (m == p) break;
        Node t = heap[p]; heap[p] = heap[m]; heap[m] = t;
        p = m;
    }
    return top;
}

int main(void) {
    int n, W;
    printf("请输入物品数 n 与背包容量 W: ");
    if (scanf("%d %d", &n, &W) != 2 || n < 1 || n > 15 || W < 0) {
        printf("输入无效!\n"); return 1;
    }
    Item it[20];
    printf("请依次输入每个物品的重量与价值:\n");
    for (int i = 0; i < n; i++) {
        scanf("%d %d", &it[i].w, &it[i].v);
        if (it[i].w <= 0 || it[i].v < 0) { printf("输入无效!\n"); return 1; }
        it[i].r = (double)it[i].v / it[i].w;
    }
    qsort(it, n, sizeof(Item), cmp_item);
    push((Node){0, 0, 0, ub(0, 0, 0, it, n, W)});
    int best = 0;
    while (hsz > 0) {
        Node cur = pop();
        if (cur.bound <= best) break;      /* 队首界≤best, 其余更不可能 */
        if (cur.i == n) { if (cur.v > best) best = cur.v; continue; }
        if (cur.w + it[cur.i].w <= W) {    /* 左孩子: 装入 */
            Node c = {cur.i + 1, cur.w + it[cur.i].w, cur.v + it[cur.i].v, 0};
            c.bound = ub(c.i, c.w, c.v, it, n, W);
            if (c.bound > best) push(c);
        }
        Node c2 = {cur.i + 1, cur.w, cur.v, 0};   /* 右孩子: 不装 */
        c2.bound = ub(c2.i, c2.w, c2.v, it, n, W);
        if (c2.bound > best) push(c2);
    }
    printf("最优价值: %d\n", best);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
/* A* 八数码: h=曼哈顿距离(可采纳且一致), 小顶堆按 f=g+h 扩展 */
#define MAXS 362880
int fact[9] = {1, 1, 2, 6, 24, 120, 720, 5040, 40320};
int dist[MAXS];                /* dist[状态] = 最小步数 g */

int enc(const int b[9]) {      /* Lehmer 编码: 排列 -> 0..9!-1 */
    int c = 0, t; for (int i = 0; i < 9; i++) { t = 0;
        for (int j = i + 1; j < 9; j++) if (b[j] < b[i]) t++;
        c += t * fact[8 - i]; }
    return c;
}
void dec(int code, int b[9]) { /* 逆编码 */
    bool u[9] = {0};
    for (int i = 0; i < 9; i++) {
        int k = code / fact[8 - i]; code %= fact[8 - i];
        for (int v = 0; v < 9; v++) { if (u[v]) continue;
            if (k == 0) { b[i] = v; u[v] = true; break; } k--; }
    }
}
int h(const int b[9]) {        /* 曼哈顿距离之和 */
    int s = 0; for (int i = 0; i < 9; i++) { if (!b[i]) continue;
        s += abs(i / 3 - (b[i] - 1) / 3) + abs(i % 3 - (b[i] - 1) % 3); }
    return s;
}
typedef struct { int idx, g, f; } Node;   /* f = g + h */
Node heap[MAXS];
int hsz = 0;
void push(Node x) {            /* 小顶堆(按 f) */
    int p = hsz++; heap[p] = x;
    while (p > 0) {
        int q = (p - 1) / 2;
        if (heap[q].f <= heap[p].f) break;
        Node t = heap[p]; heap[p] = heap[q]; heap[q] = t;
        p = q;
    }
}
Node pop(void) {
    Node top = heap[0];
    heap[0] = heap[--hsz];
    int p = 0;
    for (;;) {
        int l = 2 * p + 1, r = 2 * p + 2, m = p;
        if (l < hsz && heap[l].f < heap[m].f) m = l;
        if (r < hsz && heap[r].f < heap[m].f) m = r;
        if (m == p) break;
        Node t = heap[p]; heap[p] = heap[m]; heap[m] = t;
        p = m;
    }
    return top;
}
int main(void) {
    int b[9];
    printf("请输入初始状态(0~8, 0为空格, 共9个数): ");
    for (int i = 0; i < 9; i++) if (scanf("%d", &b[i]) != 1) return 1;
    int goal[9] = {1, 2, 3, 4, 5, 6, 7, 8, 0};
    int gcode = enc(goal), scode = enc(b);
    memset(dist, -1, sizeof(dist));
    dist[scode] = 0;
    push((Node){scode, 0, h(b)});
    int cur = -1;
    while (hsz > 0) {
        Node x = pop();
        if (x.g > dist[x.idx]) continue;   /* 过期条目 */
        if (x.idx == gcode) { cur = x.idx; break; }
        int s[9]; dec(x.idx, s);
        int z = 0; while (s[z]) z++;       /* 空格位置 */
        int r = z / 3, c = z % 3, dr[4] = {-1, 1, 0, 0}, dc[4] = {0, 0, -1, 1};
        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d], nc = c + dc[d];
            if (nr < 0 || nr > 2 || nc < 0 || nc > 2) continue;
            int nz = nr * 3 + nc, t[9]; memcpy(t, s, sizeof(t));
            t[z] = t[nz]; t[nz] = 0;
            int ni = enc(t);
            if (dist[ni] < 0 || dist[ni] > x.g + 1) {
                dist[ni] = x.g + 1;
                push((Node){ni, dist[ni], dist[ni] + h(t)});
            }
        }
    }
    if (cur < 0) { printf("无解\n"); return 0; }
    printf("最少步数: %d\n", dist[cur]);
    return 0;
}
